import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Mail, Lock, LogIn, UserPlus, ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/contexts/AuthContext';
import { useToast } from '@/hooks/use-toast';

interface AuthScreenProps {
  onBack: () => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onBack }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const { signIn, signUp, signInWithGoogle } = useAuth();
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      if (isLogin) {
        await signIn(email, password);
        toast({
          title: "Welcome back!",
          description: "You've successfully signed in.",
        });
      } else {
        await signUp(email, password);
        toast({
          title: "Account created!",
          description: "Welcome to Voice First-Aid AI.",
        });
      }
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Authentication failed. Please try again.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    try {
      await signInWithGoogle();
      toast({
        title: "Welcome!",
        description: "You've successfully signed in with Google.",
      });
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Google sign-in failed. Please try again.",
        variant: "destructive",
      });
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="w-full max-w-md mx-auto px-4"
    >
      {/* Back Button */}
      <Button
        variant="ghost"
        size="sm"
        onClick={onBack}
        className="mb-6"
      >
        <ArrowLeft className="h-4 w-4 mr-2" />
        Back
      </Button>

      {/* Header */}
      <div className="text-center mb-8">
        <div className="w-16 h-16 rounded-full primary-gradient mx-auto flex items-center justify-center mb-4">
          <span className="text-3xl">≡ƒÅÑ</span>
        </div>
        <h1 className="text-2xl font-bold text-foreground mb-2">
          {isLogin ? 'Welcome Back' : 'Create Account'}
        </h1>
        <p className="text-muted-foreground">
          {isLogin
            ? 'Sign in to access your first-aid history'
            : 'Join Voice First-Aid AI for emergency help'}
        </p>
      </div>

      {/* Form */}
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="relative">
          <Mail className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
          <Input
            type="email"
            placeholder="Email address"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="pl-12 h-14 text-lg"
            required
          />
        </div>

        <div className="relative">
          <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
          <Input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="pl-12 h-14 text-lg"
            required
            minLength={6}
          />
        </div>

        <Button
          type="submit"
          variant="default"
          size="xl"
          className="w-full"
          disabled={loading}
        >
          {loading ? (
            <div className="animate-spin h-5 w-5 border-2 border-primary-foreground border-t-transparent rounded-full" />
          ) : isLogin ? (
            <>
              <LogIn className="h-5 w-5" />
              Sign In
            </>
          ) : (
            <>
              <UserPlus className="h-5 w-5" />
              Create Account
            </>
          )}
        </Button>
      </form>

      {/* Divider */}
      <div className="flex items-center gap-4 my-6">
        <div className="flex-1 h-px bg-border" />
        <span className="text-sm text-muted-foreground">or</span>
        <div className="flex-1 h-px bg-border" />
      </div>

      {/* Google Sign In */}
      <Button
        variant="outline"
        size="lg"
        className="w-full"
        onClick={handleGoogleSignIn}
      >
        <svg className="h-5 w-5 mr-2" viewBox="0 0 24 24">
          <path
            fill="currentColor"
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
          />
          <path
            fill="currentColor"
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
          />
          <path
            fill="currentColor"
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
          />
          <path
            fill="currentColor"
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
          />
        </svg>
        Continue with Google
      </Button>

      {/* Toggle Login/Signup */}
      <p className="text-center mt-6 text-muted-foreground">
        {isLogin ? "Don't have an account? " : 'Already have an account? '}
        <button
          type="button"
          onClick={() => setIsLogin(!isLogin)}
          className="text-primary font-semibold hover:underline"
        >
          {isLogin ? 'Sign Up' : 'Sign In'}
        </button>
      </p>
    </motion.div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Mic, MicOff, Volume2, VolumeX, Stethoscope, Heart, Pill, Thermometer, Upload, Copy, Check } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
  SelectLabel,
  SelectSeparator,
  SelectGroup,
} from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { chatCompletion } from '@/lib/openai';
import { useSpeechRecognition } from '@/hooks/useSpeechRecognition';
import { useTextToSpeech } from '@/hooks/useTextToSpeech';
import { VoiceWave } from './VoiceWave';
import { useAuth } from '@/contexts/AuthContext';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp?: Date;
}

interface ChatInterfaceProps {
  onEmergencyDetected?: () => void;
}

// Suggested questions for the welcome screen
const suggestedQuestions = [
  { icon: Stethoscope, text: "What are the symptoms of flu?", emoji: "≡ƒ⌐║" },
  { icon: Heart, text: "How to manage high blood pressure?", emoji: "Γ¥ñ∩╕Å" },
  { icon: Pill, text: "Healthy meal planning for busy schedules", emoji: "≡ƒìÄ" },
  { icon: Thermometer, text: "How to improve sleep quality naturally?", emoji: "≡ƒÿ┤" },
];

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ onEmergencyDetected }) => {
  const { user } = useAuth();
  const [selectedModel, setSelectedModel] = useState('gpt-4o-mini');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [voiceEnabled, setVoiceEnabled] = useState(true);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [proxyUnreachable, setProxyUnreachable] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const handleCopy = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedId(id);
      setTimeout(() => setCopiedId(null), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const { isListening, transcript, startListening, stopListening, resetTranscript, isSupported: speechSupported } = useSpeechRecognition();
  const { speak, stop, isSpeaking, isSupported: ttsSupported } = useTextToSpeech();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    if (transcript && !isListening) {
      setInputValue(transcript);
      handleSend(transcript);
      resetTranscript();
    }
  }, [isListening, transcript]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stop(); // Stop speaking
      stopListening(); // Stop listening
    };
  }, []);

  // Load conversation from URL or Session Storage
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const paramId = params.get('conversationId');
    const storedId = sessionStorage.getItem('activeConversationId');

    // Determine which ID to use: URL param > Stored ID
    const targetId = paramId || storedId;

    if (targetId && targetId !== conversationId) {
      const fetchConversation = async () => {
        try {
          const response = await fetch(`http://localhost:3001/api/conversations/${targetId}`);
          if (response.ok) {
            const data = await response.json();

            // Map backend messages to frontend format
            const loadedMessages: Message[] = data.messages.map((m: any) => ({
              id: m._id || Date.now().toString() + Math.random(),
              role: m.role,
              content: m.content,
              timestamp: new Date(m.timestamp)
            }));

            setMessages(loadedMessages);
            setConversationId(data._id);
            sessionStorage.setItem('activeConversationId', data._id);
            console.log('Γ£à Loaded conversation:', data._id);
          } else {
            // If failed (e.g. deleted), clear storage
            sessionStorage.removeItem('activeConversationId');
            console.error('Failed to load conversation');
          }
        } catch (error) {
          console.error('Error fetching conversation:', error);
        }
      };

      fetchConversation();
    }
  }, []); // Run once on mount

  // Save conversation to MongoDB
  const saveConversation = async (newMessages: Message[], isNew: boolean = false) => {
    try {
      const userId = user?.uid || 'anonymous';
      console.log('≡ƒÆ╛ Saving conversation...', { isNew, conversationId, messageCount: newMessages.length, userId });

      if (isNew || !conversationId) {
        // Create new conversation
        const conversationData = {
          userId,
          messages: newMessages.map(m => ({
            role: m.role,
            content: m.content,
            timestamp: m.timestamp || new Date()
          })),
          isEmergency: false
        };

        console.log('≡ƒôñ Creating new conversation:', conversationData);

        const response = await fetch('http://localhost:3001/api/conversations', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(conversationData)
        });

        if (response.ok) {
          const conversation = await response.json();
          setConversationId(conversation._id);
          sessionStorage.setItem('activeConversationId', conversation._id);
          console.log('Γ£à Conversation created successfully:', conversation._id);
          return true;
        } else {
          const error = await response.json();
          console.error('Γ¥î Failed to create conversation:', error);
          return false;
        }
      } else {
        // Add message to existing conversation
        const lastMessage = newMessages[newMessages.length - 1];

        console.log('≡ƒôñ Adding message to conversation:', conversationId);

        const response = await fetch(`http://localhost:3001/api/conversations/${conversationId}/messages`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            role: lastMessage.role,
            content: lastMessage.content
          })
        });

        if (response.ok) {
          console.log('Γ£à Message added to conversation:', conversationId);
          return true;
        } else {
          const error = await response.json();
          console.error('Γ¥î Failed to add message:', error);
          return false;
        }
      }
    } catch (error) {
      console.error('Γ¥î Error saving to MongoDB:', error);
      return false;
    }
  };

  const handleSend = async (text?: string) => {
    const messageText = text || inputValue.trim();
    if (!messageText) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: messageText,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setInputValue('');
    setIsProcessing(true);

    const useProxy = (import.meta as any).env?.VITE_USE_PROXY !== 'false';
    const openaiKey = (import.meta as any).env?.VITE_OPENAI_API_KEY;

    try {
      if (openaiKey || useProxy) {
        const systemPrompt = {
          role: 'system',
          content: "You are Care Shield, a calm, empathetic AI healthcare assistant. Provide clear, actionable, and concise guidance for health and first-aid situations. When unsure, encourage seeking professional medical help. Do not provide diagnoses, only general guidance."
        };

        const history = [
          systemPrompt,
          ...messages.map((m) => ({ role: m.role as 'user' | 'assistant', content: m.content })),
          { role: 'user', content: messageText },
        ];

        const aiResponse = await chatCompletion(history, selectedModel);

        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: aiResponse,
          timestamp: new Date()
        };

        const updatedMessages = [...newMessages, assistantMessage];
        setMessages(updatedMessages);

        // Save to MongoDB - save the complete conversation
        if (messages.length === 0) {
          // First message pair - create new conversation with both messages
          await saveConversation([userMessage, assistantMessage], true);
        } else {
          // Existing conversation - add user message first, then assistant message
          await saveConversation([userMessage], false);
          await saveConversation([assistantMessage], false);
        }

        setIsProcessing(false);

        if (voiceEnabled && ttsSupported) speak(aiResponse);

        // Emergency detection
        const lower = messageText.toLowerCase();
        const isEmergency = /chest pain|heart attack|can't breathe|cant breathe|unconscious|choking|severe bleeding|stop breathing|stroke|seizure/.test(lower);
        if (isEmergency && onEmergencyDetected) onEmergencyDetected();
      }
    } catch (err: any) {
      console.error('Chat AI error', err);
      const messageText = err?.message || String(err);

      if (messageText.includes('Proxy') || messageText.includes('Failed to fetch') || messageText.includes('404')) {
        setProxyUnreachable(messageText);
      }

      const detail = messageText ? ` (${messageText})` : '';
      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `Sorry ΓÇö I am unable to reach the AI service right now. Please try again shortly.${detail}`,
        timestamp: new Date()
      };
      setMessages((prev) => [...prev, assistantMessage]);
      setIsProcessing(false);
      if (voiceEnabled && ttsSupported) speak(assistantMessage.content);
    }
  };

  const handleSuggestedQuestion = (question: string) => {
    setInputValue(question);
    handleSend(question);
  };

  const handleVoiceToggle = () => {
    if (isListening) {
      stopListening();
    } else {
      startListening();
    }
  };

  const toggleVoiceOutput = () => {
    if (isSpeaking) {
      stop();
    }
    setVoiceEnabled(!voiceEnabled);
  };

  return (
    <div className="flex flex-col h-full">
      {proxyUnreachable && (
        <div className="bg-red-900/60 text-red-100 p-3 text-sm">
          <div className="max-w-2xl mx-auto">
            <strong>Proxy unreachable:</strong> {proxyUnreachable}
            <div className="mt-2">
              Start the server proxy locally with your OpenAI key:
              <pre className="mt-1 p-2 bg-black/20 rounded">OPENAI_API_KEY=sk-... node server/index.js</pre>
            </div>
          </div>
        </div>
      )}

      {/* Messages or Welcome Screen */}
      <div className="flex-1 overflow-y-auto">
        {messages.length === 0 ? (
          /* Welcome Screen */
          <div className="flex flex-col items-center justify-center h-full px-4 py-12">
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: 'spring', stiffness: 200 }}
              className="relative mb-6"
            >
              <img
                src="/care-shield-logo.png"
                alt="Care Shield"
                className="w-24 h-24 object-contain"
              />
              <div className="absolute bottom-0 right-0 w-6 h-6 bg-green-500 rounded-full border-4 border-background"></div>
            </motion.div>

            <motion.h1
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="text-4xl font-bold text-primary mb-3"
            >
              Welcome to Care Shield
            </motion.h1>

            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="text-muted-foreground text-center max-w-md mb-2"
            >
              Your AI-powered health companion ready to answer medical questions and provide health guidance.
            </motion.p>

            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
              className="text-sm text-muted-foreground mb-8"
            >
              Click any question below to get started...
            </motion.p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-w-2xl w-full">
              {suggestedQuestions.map((question, index) => (
                <motion.button
                  key={index}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.4 + index * 0.1 }}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => handleSuggestedQuestion(question.text)}
                  className="flex items-center gap-3 p-4 rounded-xl bg-card border border-border hover:border-primary/50 hover:bg-accent transition-all text-left"
                >
                  <span className="text-2xl">{question.emoji}</span>
                  <span className="text-sm text-foreground">{question.text}</span>
                </motion.button>
              ))}
            </div>
          </div>
        ) : (
          /* Chat Messages */
          <div className="max-w-4xl mx-auto p-4 space-y-4">
            <AnimatePresence>
              {messages.map((message) => (
                <motion.div
                  key={message.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div
                    className={`max-w-[80%] p-4 rounded-2xl ${message.role === 'user'
                      ? 'bg-primary text-primary-foreground rounded-tr-sm'
                      : 'bg-card border border-border text-foreground rounded-tl-sm'
                      }`}
                  >
                    <p className="text-base leading-relaxed whitespace-pre-wrap">{message.content}</p>

                    {/* Action buttons for Assistant */}
                    {message.role === 'assistant' && (
                      <div className="flex items-center justify-end gap-1 mt-2 pt-2 border-t border-border/40">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 rounded-full hover:bg-primary/10 hover:text-primary transition-colors"
                          onClick={() => speak(message.content)}
                          title="Read aloud"
                        >
                          <Volume2 className="h-4 w-4 opacity-70" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 rounded-full hover:bg-primary/10 hover:text-primary transition-colors"
                          onClick={() => handleCopy(message.content, message.id)}
                          title="Copy text"
                        >
                          {copiedId === message.id ?
                            <Check className="h-4 w-4 text-green-500" /> :
                            <Copy className="h-4 w-4 opacity-70" />
                          }
                        </Button>
                      </div>
                    )}
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>

            {isProcessing && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="flex justify-start"
              >
                <div className="bg-card border border-border p-4 rounded-2xl rounded-tl-sm">
                  <div className="flex gap-1">
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                  </div>
                </div>
              </motion.div>
            )}

            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Voice Listening Indicator */}
      {isListening && (
        <div className="px-4 py-2 bg-primary/10 border-t border-primary/20">
          <div className="flex items-center justify-center gap-4 max-w-4xl mx-auto">
            <VoiceWave isActive={isListening} />
            <span className="text-primary font-medium">Listening...</span>
          </div>
          {transcript && (
            <p className="text-center text-muted-foreground mt-2 italic">"{transcript}"</p>
          )}
        </div>
      )}

      {/* Input Area */}
      <div className="border-t border-border bg-card/50 backdrop-blur-sm">
        <div className="max-w-4xl mx-auto p-4">
          <div className="flex items-center gap-2 mb-3">
            <Select value={selectedModel} onValueChange={setSelectedModel}>
              <SelectTrigger className="w-48">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  <SelectLabel>Recommended</SelectLabel>
                  <SelectItem value="gpt-4o-mini">Llama 3.3 70B (Recommended)</SelectItem>
                </SelectGroup>
                <SelectSeparator />
                <SelectGroup>
                  <SelectLabel>Other Models</SelectLabel>
                  <SelectItem value="gpt-4o">GPT-4o</SelectItem>
                  <SelectItem value="mixtral-8x7b">Mixtral 8x7B</SelectItem>
                </SelectGroup>
              </SelectContent>
            </Select>

            <Button variant="ghost" size="icon" onClick={toggleVoiceOutput}>
              {voiceEnabled ? <Volume2 className="h-4 w-4" /> : <VolumeX className="h-4 w-4" />}
            </Button>
          </div>

          <div className="flex gap-2">
            <Input
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSend()}
              placeholder="Ask a health question or upload a file..."
              className="flex-1 h-12"
              disabled={isListening}
            />

            {speechSupported && (
              <Button
                variant={isListening ? 'destructive' : 'outline'}
                size="icon"
                className="h-12 w-12"
                onClick={handleVoiceToggle}
              >
                {isListening ? <MicOff className="h-5 w-5" /> : <Mic className="h-5 w-5" />}
              </Button>
            )}

            <Button
              variant="default"
              size="icon"
              className="h-12 w-12"
              onClick={() => handleSend()}
              disabled={!inputValue.trim() || isProcessing}
            >
              <Send className="h-5 w-5" />
            </Button>
          </div>

          <p className="text-xs text-muted-foreground text-center mt-2">
            Care Shield can make mistakes. Check important info.
          </p>
        </div>
      </div>
    </div>
  );
};

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
